inline constexpr int kSdfGlyphCount = 113;

// Decodes one UTF-8 sequence at *text and advances it past the sequence.
// Invalid or truncated bytes decode to U+FFFD, which misses every glyph,
// so the callers' unknown-glyph fallback advance kicks in safely.
inline unsigned int SdfNextCodepoint(const char** text) {
    const unsigned char* p = reinterpret_cast<const unsigned char*>(*text);
    const unsigned char lead = p[0];
    if (lead < 0x80u) {
        *text += 1;
        return lead;
    }
    int len = 0;
    unsigned int cp = 0;
    if ((lead & 0xE0u) == 0xC0u) { len = 2; cp = lead & 0x1Fu; }
    else if ((lead & 0xF0u) == 0xE0u) { len = 3; cp = lead & 0x0Fu; }
    else if ((lead & 0xF8u) == 0xF0u) { len = 4; cp = lead & 0x07u; }
    else {
        *text += 1;
        return 0xFFFDu;
    }
    for (int i = 1; i < len; ++i) {
        const unsigned char cont = p[i];
        if ((cont & 0xC0u) != 0x80u) {
            *text += i;
            return 0xFFFDu;
        }
        cp = (cp << 6) | (cont & 0x3Fu);
    }
    *text += len;
    return cp;
}

// Linear scan is fine: the atlas holds ~90 glyphs.
inline const SdfGlyph* SdfFindGlyph(unsigned int cp) {
    for (int i = 0; i < kSdfGlyphCount; ++i) {
        if (kSdfGlyphs[i].cp == cp) {
            return &kSdfGlyphs[i];
        }
    }
    return nullptr;
}

